import bpy, json, numpy as np
from pathlib import Path
P=Path(__file__).resolve().parents[1]
bpy.ops.wm.read_factory_settings(use_empty=True);bpy.context.scene.render.fps=30;bpy.ops.import_scene.gltf(filepath=str(P/'export/mm6_jak1_runtime_lod0.glb'))
rig=next(o for o in bpy.context.scene.objects if o.type=='ARMATURE');body=next(o for o in bpy.context.scene.objects if o.type=='MESH' and o.parent is rig and 'Staff' in o.vertex_groups);names={g.index:g.name for g in body.vertex_groups};ids=np.array([v.index for v in body.data.vertices if sum(g.weight for g in v.groups if names[g.group].startswith(('B_R_Hand','B_R_Finger')))>.5]);report={}
for role,f in [('Standing',0),('Standing',55.625),('Death',0),('Dead',0)]:
 a=bpy.data.actions[role];rig.animation_data.action=a;rig.animation_data.action_slot=a.slots[0];bpy.context.scene.frame_set(int(f),subframe=f-int(f));ev=body.evaluated_get(bpy.context.evaluated_depsgraph_get());me=ev.to_mesh();co=np.array([tuple(v.co) for v in me.vertices]);ev.to_mesh_clear();inv=np.array((rig.matrix_world@rig.pose.bones['Staff'].matrix).inverted()@body.matrix_world);q=(np.c_[co[ids],np.ones(len(ids))]@inv.T)[:,:3];rad=np.linalg.norm(q[:,:2],axis=1);rad[np.abs(q[:,2])>.075]=10;sort=np.argsort(rad)[:12];report[f'{role}@{f}']={'verts':[{'id':int(ids[i]),'rad':float(rad[i]),'local':q[i].tolist(),'rest':list(body.data.vertices[int(ids[i])].co),'weights':{names[g.group]:g.weight for g in body.data.vertices[int(ids[i])].groups}} for i in sort],'finger_rot':{pb.name:list(pb.rotation_quaternion) for pb in rig.pose.bones if pb.name.startswith('B_R_Finger')},'finger_location':{pb.name:list(pb.location) for pb in rig.pose.bones if pb.name.startswith('B_R_Finger')}}
